import React, { useState } from 'react';
import { Input, Button, Toast } from '@jinx-ui/react';

const NewsletterForm: React.FC = () => {
  const [email, setEmail] = useState('');
  const [showToast, setShowToast] = useState(false);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!email) return;

    setEmail('');
    setShowToast(true);
  };

  return (
    <div className="jx-stack">
      <form className="jx-form" onSubmit={handleSubmit}>
        <label htmlFor="newsletter-email" className="jx-label">
          Email для подписки
        </label>
        <Input
          id="newsletter-email"
          type="email"
          placeholder="you@example.com"
          value={email}
          onChange={(e: React.ChangeEvent<HTMLInputElement>) => setEmail(e.target.value)}
          required
        />
        <Button type="submit" className="jx-button-primary">
          Подписаться
        </Button>
      </form>

      {showToast && (
        <Toast
          className="jx-toast jx-toast-success jx-toast-corner"
          title="Готово"
          description="Письмо отправлено на указанный адрес."
          onClose={() => setShowToast(false)}
        />
      )}
    </div>
  );
};

export default NewsletterForm;

